pub fn conditional(word: &str, person: Person, agreement: Agreement) -> String {
    Polish::new().conditional(word, person, agreement)
}

/// Every candidate for [`conditional`], most likely first; confidences sum to 1.
pub fn conditional_scored(word: &str, person: Person, agreement: Agreement) -> Vec<Candidate> {
    Polish::new().conditional_scored(word, person, agreement)
}

